SELECT p.gender, i.icustay_id, i.intime, i.outtime, i.los, d.age, d.trauma_type_code, v.charttime, v.value, v.valueuom, v.warning, row_number() OVER(PARTITION BY p.gender, i.icustay_id ORDER BY v.charttime) AS visit_rank, dense_rank() OVER(PARTITION BY p.gender, i.icustay_id ORDER BY v.value DESC) AS value_rank, percent_rank() OVER(PARTITION BY p.gender, i.icustay_id ORDER BY v.value DESC) AS value_percentile_rank FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN stayevents v ON i.stay_id = v.stay_id JOIN diagnoses_icd d ON i.hadm_id = d.hadm_id WHERE p.gender = 'M' AND age BETWEEN 68 AND 78 AND trauma_type_code IS NOT NULL AND value_rank <= 10;